const listLabelsForIssues = `-- name: ListLabelsForIssues :many
SELECT issue_labels.issue_id, labels.id, labels.project_id, labels.name, labels.color
FROM issue_labels JOIN labels ON labels.id = issue_labels.label_id
WHERE issue_labels.issue_id IN (/*SLICE:ids*/?)
ORDER BY labels.name COLLATE NOCASE
`

type ListLabelsForIssuesRow struct {
	IssueID int64
	Label   Label
}

func (q *Queries) ListLabelsForIssues(ctx context.Context, ids []int64) ([]ListLabelsForIssuesRow, error) {
	query := listLabelsForIssues
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListLabelsForIssuesRow
	for rows.Next() {
		var i ListLabelsForIssuesRow
		if err := rows.Scan(
			&i.IssueID,
			&i.Label.ID,
			&i.Label.ProjectID,
			&i.Label.Name,
			&i.Label.Color,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

